// Pure underwriting calculations. Monetary values are whole IDR; rates are decimals.
export const VERSION='2.1.0';
export const repaymentTypes=['ANNUITY','EQUAL_PRINCIPAL'];
export const facilityTypes=['WORKING_CAPITAL_KMK','TERM_LOAN','LEASING','LC_SKBDN'];
export const sum=(rows,key)=>rows.reduce((a,r)=>a+r[key],0);
export const divide=(a,b)=>Number.isFinite(a)&&Number.isFinite(b)&&b>0?a/b:null;
export const specs={
 deal:{numberOfUnits:[1,1000,true],unitCost:[1,1e15],requestedFinancingPct:[0,1],proposedCapFinancingPct:[0,1],tenorMonths:[1,120,true],annualInterestRate:[0,1],gracePeriodMonths:[0,119,true],plannedHoursPerMonthPerUnit:[1,744],billingTariffPerHour:[0,1e12],fuelConsumptionLitersPerHour:[0,10000],fuelPricePerLiter:[0,1e9],fuelPassThroughPct:[0,1],operatorCostPerUnitMonth:[0,1e15],maintenanceReservePerUnitMonth:[0,1e15],sgAndAAllocationPerUnitMonth:[0,1e15],pph23WithholdingRate:[0,.1],cashTaxRate:[0,.5],withholdingCreditRealizedPct:[0,1],debtServiceReserveMonths:[0,24,true],unrestrictedCashAvailable:[0,1e15],assetMarketValueNew:[0,1e15],forcedSaleValuePct:[0,1],annualAssetDepreciationRate:[0,.99],realizationCostPct:[0,1],realizationFixedCost:[0,1e15],liquidationDelayMonths:[0,36,true]},
 scenario:{utilizationPct:[0,1],tariffAdjustmentPct:[-.99,3],fuelPriceShockPct:[-.99,5],dsoShockDays:[0,360],interestShockBps:[0,10000],seasonalQ1Factor:[0,1],standbyHoursPerUnitMonth:[0,744]},
 policy:{minimumDSCR:[.1,10],maximumLeverage:[.1,50],minimumBankRatio:[0,1],maximumBankRatio:[1,5],cashConversionThreshold:[0,10]},
 group:{totalGroupBankExposure:[0,1e16],allBankGroupExposure:[0,1e16],bankLegalLendingLimitBMPK:[0,1e16]},
 contract:{remainingContractMonths:[0,360,true],standbyHourlyRate:[0,1e12],guaranteedHoursPerUnitMonth:[0,744]},
 bank:{totalCreditMutation:[0,1e16],totalDebitMutation:[0,1e16],intercompanyCredits:[0,1e16],nonRevenueCredits:[0,1e16],averageDailyBalance:[-1e16,1e16],endingBalance:[-1e16,1e16],bouncedChecksCount:[0,10000,true],lowBalanceDays:[0,31,true],circularTransactionCount:[0,10000,true]},
 facility:{limitAmount:[0,1e16],outstandingBalance:[0,1e16],monthlyPrincipalRepayment:[0,1e15],annualInterestRate:[0,1],collateralValueAllocated:[0,1e16]},
 spread:{revenue:[0,1e16],cogs:[0,1e16],operatingExpenses:[0,1e16],depreciationAmortization:[0,1e16],interestExpense:[0,1e16],taxExpense:[0,1e16],operatingCashFlow:[-1e16,1e16],currentAssets:[0,1e16],accountsReceivable:[0,1e16],cashAndEquivalents:[0,1e16],currentLiabilities:[0,1e16],totalGrossDebt:[0,1e16],totalAssets:[0,1e16],totalLiabilities:[0,1e16],equity:[-1e16,1e16],cashTaxesPaid:[0,1e16],increaseInNWC:[-1e16,1e16],maintenanceCapex:[0,1e16],mandatoryDistributions:[0,1e16],affiliateReceivableAdjustment:[0,1e16],auditQualityHaircutPct:[0,1]}
};
export function validateNumbers(obj,schema,label='Input',nullable=false){for(const [key,[min,max,integer]] of Object.entries(schema)){const v=obj[key];if(nullable&&v===null)continue;if(typeof v!=='number'||!Number.isFinite(v)||v<min||v>max||(integer&&!Number.isInteger(v)))throw Error(`${label}: ${key} must be ${integer?'an integer':'a number'} between ${min} and ${max}`);}}
const oneOf=(value,options,label)=>{if(!options.includes(value))throw Error(`${label}: invalid selection`);};
const bool=(obj,keys,label)=>{for(const k of keys)if(typeof obj[k]!=='boolean')throw Error(`${label}: ${k} must be true or false`);};
const string=(v,label,max=20000)=>{if(typeof v!=='string'||v.length>max)throw Error(`${label}: text expected (maximum ${max} characters)`);};
export function defaultWorkspace(){const years=[2023,2024,2025].map((y,i)=>({fiscalYear:y,periodType:'ANNUAL',periodMonths:12,sourceReference:'Illustrative financial statements',auditTier:'IN_HOUSE_UNAUDITED',auditOpinion:'WTP_UNQUALIFIED',auditQualityHaircutPct:.2,revenue:(22+i*3)*1e9,cogs:(10+i)*1e9,operatingExpenses:5e9,depreciationAmortization:1.5e9,interestExpense:1.1e9,taxExpense:.7e9,operatingCashFlow:(5+i*.5)*1e9,currentAssets:12e9,accountsReceivable:5e9,cashAndEquivalents:3e9,currentLiabilities:7e9,totalGrossDebt:12e9,totalAssets:32e9,totalLiabilities:18e9,equity:14e9,cashTaxesPaid:.7e9,increaseInNWC:.5e9,maintenanceCapex:1e9,mandatoryDistributions:.3e9,affiliateReceivableAdjustment:0,normalizationAdjustments:[]}));return {version:VERSION,lastSaved:null,source:'Illustrative equipment-finance case',borrower:{companyName:'PT Nusantara Earthworks',businessType:'MINING_CONTRACTOR',operatingSinceYear:2015,slikStatus:'COL_1_CURRENT',slikNotes:'Illustrative; obtain current iDeb with authorized access.',rkabApprovalStatus:'PENDING',ownershipStructure:'Illustrative Nusantara holding / sponsor; verify beneficial ownership.'},groupExposure:{parentHoldingName:'Nusantara Energy Resources',ultimateBeneficialOwner:'Unverified demo sponsor',totalGroupBankExposure:49e9,allBankGroupExposure:65e9,bankLegalLendingLimitBMPK:120e9,exposureScope:'Demo lender exposure before this new facility; ceiling must be approved by compliance.',guaranteeStructure:'CORPORATE_GUARANTEE',crossDefaultClauseEnforceable:false},bankReconciliation:{declaredAnnualRevenue:28e9,comparisonPeriod:'2025-01 to 2025-12',statements:Array.from({length:12},(_,i)=>({periodMonth:`2025-${String(i+1).padStart(2,'0')}`,totalCreditMutation:2.4e9,totalDebitMutation:2.1e9,intercompanyCredits:.1e9,nonRevenueCredits:0,averageDailyBalance:1.5e9,endingBalance:1.6e9,bouncedChecksCount:0,lowBalanceDays:0,circularTransactionCount:0})),annualizePartial:false},financialSpreading:{years},existingDebts:[{id:'D1',creditorName:'Example lender · KMK',facilityType:'WORKING_CAPITAL_KMK',isRevolving:true,limitAmount:5e9,outstandingBalance:2e9,monthlyPrincipalRepayment:0,annualInterestRate:.12,collateralDescription:'Receivables; allocation unverified',collateralValueAllocated:0,availabilityConfirmed:false,atLendingInstitution:true}],equipmentDeal:{numberOfUnits:5,unitCost:6e9,requestedFinancingPct:.7,proposedCapFinancingPct:16/30,tenorMonths:48,annualInterestRate:.13,repaymentStructure:'EQUAL_PRINCIPAL',gracePeriodMonths:0,plannedHoursPerMonthPerUnit:500,billingTariffPerHour:770000,fuelConsumptionLitersPerHour:28,fuelPricePerLiter:14000,fuelPassThroughPct:.5,operatorCostPerUnitMonth:20e6,maintenanceReservePerUnitMonth:20e6,sgAndAAllocationPerUnitMonth:15e6,pph23WithholdingRate:.02,cashTaxRate:.15,withholdingCreditRealizedPct:0,debtServiceReserveMonths:3,unrestrictedCashAvailable:3e9,assetMarketValueNew:30e9,forcedSaleValuePct:.65,annualAssetDepreciationRate:.15,realizationCostPct:.1,realizationFixedCost:.2e9,liquidationDelayMonths:3},offtakerContract:{offtakerName:'Illustrative mining counterparty',tierClassification:'TIER_1_CONCESSIONAIRE',remainingContractMonths:36,hasGuaranteedMinimumHours:false,standbyHourlyRate:350000,guaranteedHoursPerUnitMonth:200,hasEarlyTerminationPenalty:false,contractEvidenceVerified:false},qualitativeScorecard:{managementExperienceScore:3,offtakerCreditworthinessScore:3,contractTenorVsLoanTenorScore:2,regulatoryComplianceScore:2,equipmentMarketabilityScore:4,evidenceNotes:'Illustrative scores; independent diligence required.'},scenarios:{REQUESTED:{name:'Requested',utilizationPct:.8,tariffAdjustmentPct:0,fuelPriceShockPct:0,dsoShockDays:30,interestShockBps:0,seasonalQ1Factor:1,standbyHoursPerUnitMonth:0},PROPOSED_CAP:{name:'Proposed cap',utilizationPct:.75,tariffAdjustmentPct:0,fuelPriceShockPct:0,dsoShockDays:30,interestShockBps:0,seasonalQ1Factor:1,standbyHoursPerUnitMonth:0},DOWNSIDE:{name:'Downside',utilizationPct:.6,tariffAdjustmentPct:-.05,fuelPriceShockPct:.1,dsoShockDays:60,interestShockBps:200,seasonalQ1Factor:.8,standbyHoursPerUnitMonth:0},CUSTOM:{name:'Custom',utilizationPct:.7,tariffAdjustmentPct:0,fuelPriceShockPct:.05,dsoShockDays:45,interestShockBps:100,seasonalQ1Factor:1,standbyHoursPerUnitMonth:0}},policy:{minimumDSCR:1.25,maximumLeverage:2.5,minimumBankRatio:.7,maximumBankRatio:1.3,cashConversionThreshold:.8},memo:{analyst:'',recommendation:'Further diligence',rationale:'',conditions:'',exceptions:'',reviewDate:''},ui:{selectedScenario:'PROPOSED_CAP',commonSize:false,compact:false},auditLog:[]};}
export function validateWorkspace(w){if(!w||typeof w!=='object'||w.version!==VERSION)throw Error('Unsupported institutional workspace version');validateNumbers(w.equipmentDeal,specs.deal,'Deal');oneOf(w.equipmentDeal.repaymentStructure,repaymentTypes,'Repayment');if(w.equipmentDeal.gracePeriodMonths>=w.equipmentDeal.tenorMonths)throw Error('Grace period must be shorter than total tenor');validateNumbers(w.policy,specs.policy,'Policy');validateNumbers(w.groupExposure,specs.group,'Group');validateNumbers(w.offtakerContract,specs.contract,'Contract');bool(w.groupExposure,['crossDefaultClauseEnforceable'],'Group');bool(w.offtakerContract,['hasGuaranteedMinimumHours','hasEarlyTerminationPenalty','contractEvidenceVerified'],'Contract');oneOf(w.borrower.businessType,['MINING_CONTRACTOR','CIVIL_CONSTRUCTION','LOGISTICS','PLANTATION'],'Business type');oneOf(w.borrower.slikStatus,['COL_1_CURRENT','COL_2_SPECIAL_MENTION','COL_3_SUBSTANDARD','COL_4_DOUBTFUL','COL_5_LOSS'],'SLIK');oneOf(w.borrower.rkabApprovalStatus,['APPROVED','PENDING','EXEMPT'],'RKAB');for(const k of ['companyName','slikNotes','ownershipStructure'])string(w.borrower[k],k);if(!Number.isInteger(w.borrower.operatingSinceYear)||w.borrower.operatingSinceYear<1800||w.borrower.operatingSinceYear>2200)throw Error('Invalid operating start year');for(const k of ['parentHoldingName','ultimateBeneficialOwner','exposureScope'])string(w.groupExposure[k],k);oneOf(w.groupExposure.guaranteeStructure,['PERSONAL_GUARANTEE','CORPORATE_GUARANTEE','JOINT_SEVERAL','NONE'],'Guarantee');string(w.offtakerContract.offtakerName,'Offtaker');oneOf(w.offtakerContract.tierClassification,['TIER_1_CONCESSIONAIRE','TIER_2_MID_MINER','SUB_CONTRACTOR'],'Offtaker tier');for(const key of ['REQUESTED','PROPOSED_CAP','DOWNSIDE','CUSTOM']){validateNumbers(w.scenarios[key],specs.scenario,key);if(w.equipmentDeal.annualInterestRate+w.scenarios[key].interestShockBps/10000>1)throw Error('Combined annual rate exceeds model range');generateAmortizationSchedule(1,w.equipmentDeal.annualInterestRate+w.scenarios[key].interestShockBps/10000,w.equipmentDeal.tenorMonths,w.equipmentDeal.repaymentStructure,w.equipmentDeal.gracePeriodMonths,w.scenarios[key].seasonalQ1Factor);string(w.scenarios[key].name,'Scenario name');}if(!Array.isArray(w.existingDebts)||w.existingDebts.length>100)throw Error('Maximum 100 existing facilities');const ids=new Set();for(const d of w.existingDebts){validateNumbers(d,specs.facility,'Facility');if(d.outstandingBalance>d.limitAmount)throw Error('Facility outstanding exceeds limit');if(ids.has(d.id))throw Error('Duplicate facility ID');ids.add(d.id);string(d.id,'Facility ID');string(d.creditorName,'Creditor');string(d.collateralDescription,'Collateral description');bool(d,['isRevolving','availabilityConfirmed','atLendingInstitution'],'Facility');oneOf(d.facilityType,facilityTypes,'Facility type');if(d.isRevolving&&d.facilityType!=='WORKING_CAPITAL_KMK')throw Error('Only KMK may be revolving in this model');}
 validateBank(w.bankReconciliation);validateSpreads(w.financialSpreading.years);for(const k of ['managementExperienceScore','offtakerCreditworthinessScore','contractTenorVsLoanTenorScore','regulatoryComplianceScore','equipmentMarketabilityScore'])validateNumbers(w.qualitativeScorecard,{[k]:[1,5,true]},'Scorecard');string(w.qualitativeScorecard.evidenceNotes,'Scorecard evidence');for(const k of ['analyst','recommendation','rationale','conditions','exceptions','reviewDate'])string(w.memo[k],'Memo '+k);oneOf(w.memo.recommendation,['Further diligence','Support with conditions','Restructure / reduce limit','Decline'],'Recommendation');if(w.memo.reviewDate&&!/^\d{4}-\d{2}-\d{2}$/.test(w.memo.reviewDate))throw Error('Review date must use YYYY-MM-DD');bool(w.ui,['commonSize','compact'],'UI');oneOf(w.ui.selectedScenario,Object.keys(w.scenarios),'Selected scenario');if(!Array.isArray(w.auditLog)||w.auditLog.length>1000)throw Error('Invalid local change history');return w;}
export function validateBank(bank){if(!Array.isArray(bank.statements)||bank.statements.length>120)throw Error('Maximum 120 bank statement months');if(!Number.isFinite(bank.declaredAnnualRevenue)||bank.declaredAnnualRevenue<0)throw Error('Declared revenue must be zero or positive');bool(bank,['annualizePartial'],'Bank');string(bank.comparisonPeriod,'Bank comparison period');const seen=new Set();for(const m of bank.statements){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(m.periodMonth)||seen.has(m.periodMonth))throw Error('Bank periods must be unique YYYY-MM values');seen.add(m.periodMonth);validateNumbers(m,specs.bank,'Bank month');if(m.intercompanyCredits+m.nonRevenueCredits>m.totalCreditMutation)throw Error('Excluded credits exceed gross bank credits');}return bank;}
export function validateSpreads(years){if(!Array.isArray(years)||years.length>10)throw Error('Maximum 10 spread periods');const periods=new Set();for(const y of years){if(!Number.isInteger(y.fiscalYear)||y.fiscalYear<1900||y.fiscalYear>2200)throw Error('Invalid fiscal year');oneOf(y.periodType,['ANNUAL','YTD'],'Period type');if(!Number.isInteger(y.periodMonths)||y.periodMonths<1||y.periodMonths>12||(y.periodType==='ANNUAL'&&y.periodMonths!==12))throw Error('Annual periods require 12 months; YTD requires 1–12');const k=y.fiscalYear+y.periodType;if(periods.has(k))throw Error('Duplicate financial period');periods.add(k);validateNumbers(y,specs.spread,'Financial spread',true);if(y.auditQualityHaircutPct===null)throw Error('Audit haircut required');oneOf(y.auditTier,['BIG_4','TIER_2_AFFILIATED','LOCAL_KAP','IN_HOUSE_UNAUDITED'],'Audit tier');oneOf(y.auditOpinion,['WTP_UNQUALIFIED','WDP_QUALIFIED','DISCLAIMER_ADVERSE'],'Audit opinion');string(y.sourceReference,'Source reference');if(!Array.isArray(y.normalizationAdjustments)||y.normalizationAdjustments.length>50)throw Error('Maximum 50 normalization adjustments');for(const a of y.normalizationAdjustments){string(a.description,'Adjustment rationale');if(!Number.isFinite(a.amount))throw Error('Adjustment amount required');bool(a,['enabled'],'Adjustment');}}return years;}
export function migrateWorkspace(raw){if(raw?.version===VERSION)return validateWorkspace(structuredClone(raw));if(raw?.version==='2.0.0'){const w=structuredClone(raw);w.version=VERSION;for(const y of w.financialSpreading?.years||[])for(const k of Object.keys(specs.spread))if(y[k]===undefined&&k!=='auditQualityHaircutPct')y[k]=null;try{return validateWorkspace(w);}catch(err){throw Error('Legacy workspace requires explicit completion of missing inputs before restore: '+err.message);}}throw Error('Unrecognized workspace version; current data has not been changed');}
export function generateAmortizationSchedule(principal,annualRate,tenorMonths,structure,gracePeriodMonths=0,seasonalQ1Factor=1){validateNumbers({principal,annualRate,tenorMonths,gracePeriodMonths,seasonalQ1Factor},{principal:[0,1e16],annualRate:[0,1],tenorMonths:[1,120,true],gracePeriodMonths:[0,119,true],seasonalQ1Factor:[0,1]});oneOf(structure,repaymentTypes,'Repayment');if(gracePeriodMonths>=tenorMonths)throw Error('Grace must be shorter than tenor');const rate=annualRate/12,weights=Array.from({length:tenorMonths},(_,i)=>i<gracePeriodMonths?0:(i%12<3?seasonalQ1Factor:1));const totalWeight=weights.reduce((a,b)=>a+b,0);if(totalWeight===0&&principal>0)throw Error('No amortizing months remain with seasonal weighting');let balance=principal;const discount=weights.reduce((a,v,i)=>a+v/(1+rate)**(i+1-gracePeriodMonths),0),annuity=discount?principal/discount:0;const schedule=[];for(let i=0;i<tenorMonths;i++){const interest=balance*rate;let paid=weights[i]===0?0:structure==='EQUAL_PRINCIPAL'?principal*weights[i]/totalWeight:Math.max(0,annuity*weights[i]-interest);if(i===tenorMonths-1)paid=balance;paid=Math.min(balance,paid);schedule.push({month:i+1,beginningBalance:balance,principalPayment:paid,interestPayment:interest,totalInstallment:paid+interest,endingBalance:Math.max(0,balance-paid)});balance=schedule.at(-1).endingBalance;}return schedule;}
export function calculateProjectCFADS(deal,scenario,contract=null){const hours=deal.plannedHoursPerMonthPerUnit*scenario.utilizationPct*deal.numberOfUnits;const hourlyTariff=deal.billingTariffPerHour*(1+scenario.tariffAdjustmentPct);const operatingRevenue=hours*hourlyTariff;const standbyHours=contract?.hasGuaranteedMinimumHours&&contract.contractEvidenceVerified?Math.min(scenario.standbyHoursPerUnitMonth,Math.max(0,contract.guaranteedHoursPerUnitMonth-deal.plannedHoursPerMonthPerUnit*scenario.utilizationPct))*deal.numberOfUnits:0;const standbyRevenue=standbyHours*(contract?.standbyHourlyRate||0);const grossRevenue=operatingRevenue+standbyRevenue,withholding=grossRevenue*deal.pph23WithholdingRate;const fuel=hours*deal.fuelConsumptionLitersPerHour*deal.fuelPricePerLiter*(1+scenario.fuelPriceShockPct)*(1-deal.fuelPassThroughPct);const operator=deal.numberOfUnits*deal.operatorCostPerUnitMonth,maintenance=deal.numberOfUnits*deal.maintenanceReservePerUnitMonth,overhead=deal.numberOfUnits*deal.sgAndAAllocationPerUnitMonth;const ebitda=grossRevenue-fuel-operator-overhead;const taxableProxy=Math.max(0,ebitda-maintenance),grossCashTax=taxableProxy*deal.cashTaxRate;const creditRealized=Math.min(grossCashTax,withholding*deal.withholdingCreditRealizedPct),cashTax=grossCashTax-creditRealized;const cfads=grossRevenue-withholding-fuel-operator-overhead-maintenance-cashTax;return {billedHours:hours,operatingRevenue,standbyRevenue,grossRevenue,pph23WithholdingDeduction:withholding,netCashReceipts:grossRevenue-withholding,fuelCost:fuel,operatorCost:operator,maintenanceReserve:maintenance,allocatedOverhead:overhead,totalOperatingCashOutflows:fuel+operator+overhead,projectEBITDA:ebitda,grossCashTax,withholdingCreditRealized:creditRealized,cashTax,monthlyCFADS:cfads,annualizedCFADS:cfads*12};}
export function existingDebtSummary(debts,interestShockBps=0,months=12){let service=0,committed=0,confirmed=0;for(const d of debts){let outstanding=d.outstandingBalance;const rate=(d.annualInterestRate+interestShockBps/10000)/12;for(let m=0;m<months;m++){const principal=d.isRevolving||d.facilityType==='LC_SKBDN'?0:Math.min(outstanding,d.monthlyPrincipalRepayment);service+=principal+outstanding*rate;outstanding-=principal;}if(d.isRevolving&&d.facilityType==='WORKING_CAPITAL_KMK'){const headroom=Math.max(0,d.limitAmount-d.outstandingBalance);committed+=headroom;if(d.availabilityConfirmed)confirmed+=headroom;}}return {annualDebtService:service,undrawnKMKHeadroom:committed,confirmedKMKHeadroom:confirmed,totalOutstanding:sum(debts,'outstandingBalance')};}
export function evaluateScenario(w,key){const deal=w.equipmentDeal,scenario=w.scenarios[key],amount=deal.numberOfUnits*deal.unitCost*(key==='REQUESTED'?deal.requestedFinancingPct:deal.proposedCapFinancingPct);const schedule=generateAmortizationSchedule(amount,deal.annualInterestRate+scenario.interestShockBps/10000,deal.tenorMonths,deal.repaymentStructure,deal.gracePeriodMonths,scenario.seasonalQ1Factor);const bridge=calculateProjectCFADS(deal,scenario,w.offtakerContract),existing=existingDebtSummary(w.existingDebts,scenario.interestShockBps),newService=sum(schedule.slice(0,12),'totalInstallment'),service=newService+existing.annualDebtService;const workingCapitalDSODrag=scenario.dsoShockDays/360*bridge.grossRevenue*12;const year1CFADS=bridge.annualizedCFADS-workingCapitalDSODrag;const reserve=newService/12*deal.debtServiceReserveMonths;const liquidity=deal.unrestrictedCashAvailable+existing.confirmedKMKHeadroom;const groupExposure=w.groupExposure.totalGroupBankExposure+amount;const utilization=divide(groupExposure,w.groupExposure.bankLegalLendingLimitBMPK);const dscr=divide(bridge.annualizedCFADS,service),year1=divide(year1CFADS,service),ceilingBreach=utilization!==null&&utilization>1;const contractMatch=w.offtakerContract.remainingContractMonths>=deal.tenorMonths;const breakEven=solveBreakEvenUtilization(deal,scenario,service,w.policy.minimumDSCR,w.offtakerContract);const collateral=evaluateCollateralCoverageTimeline(deal,schedule);const flags=[];if(bridge.annualizedCFADS<=0)flags.push('Operating cash deficit');if(year1!==null&&year1<w.policy.minimumDSCR)flags.push('Year-1 DSCR below covenant');if(dscr!==null&&dscr<w.policy.minimumDSCR)flags.push('Steady-state DSCR below covenant');if(liquidity-reserve-workingCapitalDSODrag<0)flags.push('Liquidity shortfall');if(ceilingBreach)flags.push('Lender group ceiling exceeded');if(utilization===null)flags.push('Group ceiling unavailable');if(!contractMatch)flags.push('Contract expires before loan maturity');if(!w.offtakerContract.contractEvidenceVerified)flags.push('Contract protections unverified');if(w.borrower.rkabApprovalStatus==='PENDING')flags.push('Regulatory evidence pending');if(!['COL_1_CURRENT','COL_2_SPECIAL_MENTION'].includes(w.borrower.slikStatus))flags.push('Adverse reported SLIK classification');return {key,scenario,amount,equityContribution:deal.numberOfUnits*deal.unitCost-amount,schedule,bridge,existing,annualDebtServiceYear1:service,newFacilityDebtServiceYear1:newService,steadyStateDSCR:dscr,year1PostShockCFADS:year1CFADS,year1PostShockDSCR:year1,workingCapitalDSODrag,debtServiceReserveRequired:reserve,totalAvailableLiquidity:liquidity,netLiquidityHeadroom:liquidity-reserve-workingCapitalDSODrag,groupExposure,groupBMPKUtilization:utilization,ceilingBreach,contractMatch,breakEven,collateral,flags,status:flags.length?'REVIEW REQUIRED':'WITHIN SCREENING LIMITS'};}
export function solveBreakEvenUtilization(deal,scenario,annualService,targetDSCR,contract=null){
 if(annualService===0)return {value:null,status:'NO_DEBT_SERVICE',residual:null};
 const bridge=u=>calculateProjectCFADS(deal,{...scenario,utilizationPct:u},contract),target=targetDSCR*annualService;
 const f=u=>bridge(u).annualizedCFADS-target;
 if(f(0)>=0)return {value:0,status:'FEASIBLE',residual:f(0)};
 // CFADS is piecewise affine: idle guarantees, positive-tax threshold, and tax-credit floor.
 // Solve each affine segment algebraically rather than using the blueprint's inconsistent reverse-tax formula.
 let knots=[0];
 if(contract?.hasGuaranteedMinimumHours&&contract.contractEvidenceVerified){const max=deal.plannedHoursPerMonthPerUnit;knots.push(Math.max(0,(contract.guaranteedHoursPerUnitMonth-scenario.standbyHoursPerUnitMonth)/max),contract.guaranteedHoursPerUnitMonth/max);}
 knots=[...new Set(knots)].sort((a,b)=>a-b);
 const affineRoot=(fn,lo,hi)=>{const a=fn(lo),s=(fn(hi)-a)/(hi-lo);return Math.abs(s)>1e-8?lo-a/s:null;};
 for(let pass=0;pass<2;pass++){const add=[];for(let i=0;i<knots.length;i++){const lo=knots[i],hi=knots[i+1]??lo+1;for(const fn of [u=>{const b=bridge(u);return b.projectEBITDA-b.maintenanceReserve;},u=>{const b=bridge(u);return b.grossCashTax-b.pph23WithholdingDeduction*deal.withholdingCreditRealizedPct;}]){const root=affineRoot(fn,lo,hi);if(root!==null&&root>lo+1e-10&&(i===knots.length-1||root<hi-1e-10))add.push(root);}}knots=[...new Set([...knots,...add])].sort((a,b)=>a-b);}
 for(let i=0;i<knots.length;i++){const lo=knots[i],hi=knots[i+1]??lo+1;const root=affineRoot(f,lo,hi);if(root!==null&&root>=lo-1e-9&&(i===knots.length-1||root<=hi+1e-9)&&Math.abs(f(root))<=Math.max(.01,target*1e-10))return {value:Math.max(0,root),status:root>1?'ABOVE_CAPACITY':'FEASIBLE',residual:f(root)};}
 return {value:null,status:'NONPOSITIVE_MARGIN',residual:null};
}
export function suggestedAuditHaircut(tier,opinion){const base={BIG_4:0,TIER_2_AFFILIATED:.05,LOCAL_KAP:.1,IN_HOUSE_UNAUDITED:.2}[tier];return Math.min(1,base+(opinion==='WDP_QUALIFIED'?.1:opinion==='DISCLAIMER_ADVERSE'?.3:0));}
export function evaluateCollateralCoverageTimeline(deal,schedule){const first={month:0,endingBalance:schedule[0]?.beginningBalance||0};return [first,...schedule].map(r=>{const market=deal.assetMarketValueNew*(1-deal.annualAssetDepreciationRate)**((r.month+deal.liquidationDelayMonths)/12);const grossFSV=market*deal.forcedSaleValuePct;const net=Math.max(0,grossFSV*(1-deal.realizationCostPct)-deal.realizationFixedCost);return {month:r.month,outstandingDebt:r.endingBalance,assetMarketValue:market,grossForcedSaleValue:grossFSV,netForcedSaleValue:net,negativeEquityGap:Math.max(0,r.endingBalance-net),netCoverage:divide(net,r.endingBalance)};});}
export function evaluateBankStatementIntegrity(bank,policy={minimumBankRatio:.7,maximumBankRatio:1.3}){validateBank(bank);const rows=bank.statements.slice().sort((a,b)=>a.periodMonth.localeCompare(b.periodMonth));if(!rows.length)return {ratio:null,adjustedCredits:null,annualizedCredits:null,flag:'MISSING',observations:['No bank statements ingested']};const gross=sum(rows,'totalCreditMutation'),excluded=sum(rows,'intercompanyCredits')+sum(rows,'nonRevenueCredits'),adjusted=gross-excluded,annualized=bank.annualizePartial?adjusted/rows.length*12:null;const compared=bank.annualizePartial?annualized:adjusted;const ratio=divide(compared,bank.declaredAnnualRevenue),observations=[];const full=rows.length===12&&rows.every((r,i)=>i===0||monthIndex(r.periodMonth)-monthIndex(rows[i-1].periodMonth)===1);if(!full&&!bank.annualizePartial)observations.push('Period mismatch: match declared revenue to the covered bank periods');if(bank.annualizePartial)observations.push('Partial bank turnover annualized by analyst assumption; seasonality not modeled');if(ratio===null)observations.push('Reported comparison revenue unavailable or zero');if(ratio!==null&&(ratio<policy.minimumBankRatio||ratio>policy.maximumBankRatio))observations.push('Turnover divergence outside screening range');const bounced=sum(rows,'bouncedChecksCount'),low=sum(rows,'lowBalanceDays'),circular=sum(rows,'circularTransactionCount');if(bounced)observations.push(`${bounced} rejected / bounced transactions`);if(low)observations.push(`${low} reported low-balance days`);if(circular)observations.push(`${circular} reported circular transactions; investigate provenance`);return {ratio,grossCredits:gross,excludedCredits:excluded,adjustedCredits:adjusted,annualizedCredits:annualized,averageBalance:sum(rows,'averageDailyBalance')/rows.length,bouncedChecks:bounced,lowBalanceDays:low,circularTransactions:circular,periods:rows.length,flag:observations.length?'REVIEW':'RECONCILED',observations:observations.length?observations:['Period-aligned adjusted credits within screening range; cash turnover does not prove revenue recognition']};}
function monthIndex(s){const [y,m]=s.split('-').map(Number);return y*12+m;}
export function calculateSpread(y){const available=(...keys)=>keys.every(k=>Number.isFinite(y[k]));const gross=available('revenue','cogs')?y.revenue-y.cogs:null,ebit=gross!==null&&available('operatingExpenses')?gross-y.operatingExpenses:null,ebitda=ebit!==null&&available('depreciationAmortization')?ebit+y.depreciationAmortization:null;const adjustments=y.normalizationAdjustments.filter(a=>a.enabled).reduce((s,a)=>s+a.amount,0),normalized=ebitda!==null?ebitda+adjustments:null,adjusted=normalized===null?null:normalized>0?normalized*(1-y.auditQualityHaircutPct):normalized;const net=ebit!==null&&available('interestExpense','taxExpense')?ebit-y.interestExpense-y.taxExpense:null;const cfads=adjusted!==null&&available('cashTaxesPaid','increaseInNWC','maintenanceCapex','mandatoryDistributions')?adjusted-y.cashTaxesPaid-y.increaseInNWC-y.maintenanceCapex-y.mandatoryDistributions:null;const balanceDiff=available('totalAssets','totalLiabilities','equity')?y.totalAssets-y.totalLiabilities-y.equity:null;return {grossProfit:gross,ebit,ebitda,normalizationTotal:adjustments,normalizedEbitda:normalized,haircutAmount:normalized!==null&&normalized>0?normalized*y.auditQualityHaircutPct:0,adjustedEbitda:adjusted,netIncome:net,normalizedCFADS:cfads,nwc:available('currentAssets','currentLiabilities')?y.currentAssets-y.currentLiabilities:null,tangibleNetWorth:available('equity','affiliateReceivableAdjustment')?y.equity-y.affiliateReceivableAdjustment:null,interestCoverage:divide(ebit,y.interestExpense),cashConversion:divide(y.operatingCashFlow,ebit),leverage:divide(y.totalGrossDebt,adjusted),balanceDiff,balanceStatus:balanceDiff===null?'MISSING':Math.abs(balanceDiff)<=Math.max(1,y.totalAssets*1e-6)?'BALANCED':'MISMATCH'};}
export function qualitativeScore(q){const score=q.managementExperienceScore*.25+((q.offtakerCreditworthinessScore+q.contractTenorVsLoanTenorScore)/2)*.35+q.regulatoryComplianceScore*.2+q.equipmentMarketabilityScore*.2;return {score,grade:score>=4.5?'A':score>=3.75?'B+':score>=3?'B':'C',weights:{management:.25,offtaker:.35,regulatory:.2,asset:.2}};}
export function indicativeDebtCap(w,key='PROPOSED_CAP'){const s=w.scenarios[key],cf=calculateProjectCFADS(w.equipmentDeal,s,w.offtakerContract).annualizedCFADS-s.dsoShockDays/360*calculateProjectCFADS(w.equipmentDeal,s,w.offtakerContract).grossRevenue*12,existing=existingDebtSummary(w.existingDebts,s.interestShockBps).annualDebtService;const unit=generateAmortizationSchedule(1,w.equipmentDeal.annualInterestRate+s.interestShockBps/10000,w.equipmentDeal.tenorMonths,w.equipmentDeal.repaymentStructure,w.equipmentDeal.gracePeriodMonths,s.seasonalQ1Factor);const service=sum(unit.slice(0,12),'totalInstallment');const capacity=cf/w.policy.minimumDSCR-existing;return service>0?Math.min(w.equipmentDeal.numberOfUnits*w.equipmentDeal.unitCost,Math.max(0,capacity/service)):null;}
